const record = $('Get a record').first().json;
const azienda = record.fields || record;
const capitoliRaw = $('Search records').all();

const capitoli = capitoliRaw
  .sort((a, b) => {
    const fA = a.json.fields || a.json;
    const fB = b.json.fields || b.json;
    const oA = String(fA['Ordine'] || '');
    const oB = String(fB['Ordine'] || '');
    return oA.localeCompare(oB, undefined, { numeric: true });
  })
  .map(c => {
    const f = c.json.fields || c.json;
    return {
      numero: f['Numero Capitolo'] || '',
      titolo: f['Titolo Capitolo'] || '',
      contenuto: f['Contenuto Generato'] || ''
    };
  });

return [{
  json: {
    azienda: {
      ragioneSociale: azienda['Ragione Sociale'] || '',
      partitaIva: azienda['Partita IVA'] || '',
      codiceAteco: azienda['Codice ATECO'] || '',
      descrizioneAttivita: azienda['Descrizione Attività'] || '',
      nDipendenti: String(azienda['N° Dipendenti'] || ''),
      indirizzoSede: azienda['Indirizzo Sede'] || '',
      categoriaRischio: azienda['Categoria Rischio'] || '',
      dataCreazione: azienda['Data creazione'] || '',
    },
    capitoli: capitoli
  }
}];

const record = $('Get a record').first().json;
const azienda = record.fields || record;
const capitoliRaw = $('Search records').all();
const capitoli = capitoliRaw
  .sort((a, b) => {
    const fA = a.json.fields || a.json;
    const fB = b.json.fields || b.json;
    return String(fA['Ordine'] || '').localeCompare(String(fB['Ordine'] || ''), undefined, { numeric: true });
  })
  .map(c => {
    const f = c.json.fields || c.json;
    return {
      numero: f['Numero Capitolo'] || '',
      titolo: f['Titolo Capitolo'] || '',
      contenuto: f['Contenuto Generato'] || ''
    };
  });

// Splitta capitoli troppo lunghi (>15000 caratteri) per heading ##/###
const MAX_LEN = 15000;
const splitCapitoli = [];
for (const cap of capitoli) {
  if (cap.contenuto.length <= MAX_LEN) {
    splitCapitoli.push(cap);
  } else {
    // Splitta per heading di livello ## o ###
    const parts = cap.contenuto.split(/(?=\n## |\n### )/);
    let chunk = '';
    for (const part of parts) {
      if ((chunk + part).length > MAX_LEN && chunk.length > 0) {
        splitCapitoli.push({ numero: cap.numero, titolo: cap.titolo, contenuto: chunk });
        chunk = part;
      } else {
        chunk += part;
      }
    }
    if (chunk.length > 0) {
      splitCapitoli.push({ numero: cap.numero, titolo: cap.titolo, contenuto: chunk });
    }
  }
}

const az = {
  ragioneSociale: azienda['Ragione Sociale'] || '',
  partitaIva: azienda['Partita IVA'] || '',
  codiceAteco: azienda['Codice ATECO'] || '',
  descrizioneAttivita: azienda['Descrizione Attività'] || '',
