  indirizzoSede: azienda['Indirizzo Sede'] || '',
  categoriaRischio: azienda['Categoria Rischio'] || '',
  dataCreazione: azienda['Data creazione'] || '',
};

// Batch da 1 capitolo ciascuno
const batches = splitCapitoli.map(c => [c]);

return [{ json: { azienda: az, batches: batches, totalBatches: batches.length } }];

